def transform(grid):
    h, w = len(grid), len(grid[0])

    # The solid-color lines divide the grid into independent regions.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def spans(n, separators):
        result = []
        start = 0
        for pos in separators:
            if start < pos:
                result.append((start, pos))
            start = pos + 1
        if start < n:
            result.append((start, n))
        return result

    row_spans = spans(h, sep_rows)
    col_spans = spans(w, sep_cols)

    # Identify the background and the sparse marker color.
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    line_colors = {grid[r][0] for r in sep_rows}
    line_colors |= {grid[0][c] for c in sep_cols}
    background = max((v for v in counts if v not in line_colors),
                     key=lambda v: counts[v])
    marker = min((v for v in counts if v not in line_colors and v != background),
                 key=lambda v: counts[v])

    return [
        [1 if sum(grid[r][c] == marker
                  for r in range(r0, r1)
                  for c in range(c0, c1)) == 2 else background
         for c0, c1 in col_spans]
        for r0, r1 in row_spans
    ]
